<template>
  <div class="module">
    <div class="module-head">
      <h2>🤖 数字人导诊</h2>
      <p>专属虚拟养生顾问小颐：自由对话、语音输入、语音播报。</p>
    </div>

    <div class="stage">
      <div class="avatar" :class="{ speaking: speaking, listening: recording }">
        <div class="avatar-face">
          <div class="eye left"></div>
          <div class="eye right"></div>
          <div class="mouth"></div>
        </div>
        <div class="ring"></div>
        <div class="avatar-name">小颐</div>
      </div>
      <div class="stage-status">
        <span v-if="speaking" class="status-tag speaking-tag">🔊 正在播报…</span>
        <span v-else-if="recording" class="status-tag rec-tag">● 正在聆听（点击麦克风停止）</span>
        <span v-else class="status-tag idle-tag">在线 · 随时为你解答</span>
      </div>
    </div>

    <!-- 对话记录 -->
    <div class="chat-box" ref="chatBox">
      <div
        v-for="(m, i) in messages"
        :key="i"
        class="msg"
        :class="m.from === 'user' ? 'msg-user' : 'msg-bot'"
      >
        <span v-if="m.from === 'bot'" class="msg-avatar">颐</span>
        <div class="msg-bubble">
          <span v-if="m.interim" class="interim-flag">（识别中…）</span>{{ m.text }}
        </div>
      </div>
      <div v-if="interimText" class="msg msg-user">
        <div class="msg-bubble interim">{{ interimText }}…</div>
      </div>
    </div>

    <!-- 快捷话题 -->
    <div class="topics">
      <button
        v-for="t in topics"
        :key="t.q"
        class="topic"
        @click="ask(t)"
      >
        {{ t.q }}
      </button>
    </div>

    <!-- 输入区：麦克风 + 文字 -->
    <div class="input-row">
      <button
        class="mic-btn"
        :class="{ recording: recording, disabled: !supportsSpeech }"
        :title="recording ? '点击停止识别' : '点击开始语音识别'"
        @click="toggleRecord"
      >
        <span class="mic-icon">{{ recording ? '⏹' : '🎤' }}</span>
        <span class="mic-text">{{ recording ? '点击停止识别' : '点击开始识别' }}</span>
      </button>
      <input
        v-model="inputText"
        type="text"
        class="chat-input"
        placeholder="输入你的养生问题，回车发送…"
        @keyup.enter="send"
      />
      <button class="send-btn" @click="send">发送</button>
    </div>

    <div class="controls">
      <button class="btn" @click="stopSpeak">⏹ 停止播报</button>
      <button class="btn" @click="clearChat">🗑 清空对话</button>
      <label class="switch">
        <input type="checkbox" v-model="voiceOn" /> 语音播报
      </label>
    </div>
  </div>
</template>

<script>
const TOPICS = [
  { q: '今天怎么养生？', a: '建议早睡早起，晨起一杯温水，午后可做八段锦舒展筋骨，饮食宜清淡温润。' },
  { q: '失眠怎么办？', a: '睡前一小时远离屏幕，泡脚十五分钟，饮用酸枣仁茶，并保持卧室黑暗安静。' },
  { q: '秋季如何调理？', a: '秋季重在润肺防燥，可食雪梨、百合、银耳，注意增减衣物，避免着凉。' },
  { q: '久坐如何保健？', a: '每小时起身活动，做肩颈拉伸与眼部远眺，日常多饮温水促进代谢。' },
  { q: '怎么改善气色？', a: '保证睡眠与蛋白质摄入，适度有氧运动，多吃红枣、枸杞等补益食材。' }
]

/* 中医养生知识库：按关键词评分匹配，支持自由对话 */
const KB = [
  {
    keys: ['失眠', '睡不着', '入睡困难', '多梦', '早醒', '睡眠差', '睡眠不好', '翻来覆去', '睡眠质量'],
    reply: '【失眠调理】中医认为失眠多与心肝火旺、心脾两虚有关。\n🌙 起居：睡前1小时远离手机，用40℃温水泡脚15分钟；\n🍵 食疗：酸枣仁莲子粥、桂圆百合汤助眠；\n💆 穴位：按揉神门穴、内关穴各3分钟；\n🧘 配合「睡前正念冥想」课程效果更佳。'
  },
  {
    keys: ['疲劳', '累', '乏力', '没劲', '疲惫', '困倦', '嗜睡', '气短'],
    reply: '【疲劳调理】多是气虚所致，气不足则神疲乏力。\n🍚 食疗：黄芪党参乌鸡汤、山药薏米粥补中益气；\n💆 穴位：艾灸足三里、气海穴，每天10分钟；\n🏃 运动：八段锦「两手托天理三焦」，晨起练习5分钟；\n😴 作息：23点前入睡，避免过度耗气。'
  },
  {
    keys: ['脾胃', '胃胀', '胃痛', '消化不良', '食欲不振', '没胃口', '腹胀', '腹泻', '拉肚子', '便秘', '反酸', '嗳气'],
    reply: '【脾胃调理】脾主运化，胃主受纳，脾胃不和则百病生。\n🍲 食疗：四神汤（茯苓、莲子、芡实、山药）健脾祛湿；小米南瓜粥养胃；\n💆 穴位：常按足三里、中脘穴，饭后顺时针摩腹36圈；\n🚫 忌：生冷瓜果、肥甘厚腻、暴饮暴食；\n🧘 建议：每餐七分饱，细嚼慢咽。'
  },
  {
    keys: ['头痛', '头疼', '偏头痛', '头晕', '头昏', '太阳穴疼'],
    reply: '【头痛调理】需分型而治：肝阳上亢多胀痛，血虚多隐痛，痰湿多昏重。\n💆 穴位：按揉太阳穴、风池穴、合谷穴各2分钟；\n🍵 食疗：菊花决明子茶清肝明目；当归红枣茶养血；\n😴 保证充足睡眠，避免长时间低头；\n⚠️ 若突发剧烈头痛或持续加重，请及时就医。'
  },
  {
    keys: ['焦虑', '郁闷', '烦躁', '压力大', '心情不好', '抑郁', '心慌', '易怒', '发脾气'],
    reply: '【情志调理】肝主疏泄，情绪不畅则肝气郁结。\n🧘 疏解：玫瑰花陈皮茶疏肝理气，八段锦「攒拳怒目增气力」发泄情绪；\n💆 穴位：太冲穴（消气穴）、膻中穴各按3分钟；\n🚶 运动：每日快走30分钟，晒晒太阳；\n💬 和朋友倾诉、写日记也是很好的疏肝方式。'
  },
  {
    keys: ['咳嗽', '感冒', '嗓子疼', '喉咙痛', '咽喉', '有痰', '干咳', '鼻塞', '流鼻涕'],
    reply: '【肺系调理】肺为娇脏，易受外邪侵袭。\n🍐 食疗：冰糖雪梨羹润肺止咳；川贝炖雪梨适合干咳；罗汉果茶利咽；\n💆 穴位：按揉列缺穴、尺泽穴；\n🧣 起居：注意颈部保暖，避免辛辣刺激；\n⚠️ 症状超过一周或发热，建议就医检查。'
  },
  {
    keys: ['怕冷', '手脚冰凉', '宫寒', '阳虚', '腰膝酸冷', '畏寒'],
    reply: '【阳虚调理】阳气不足则畏寒肢冷，需要温补阳气。\n🍲 食疗：当归生姜羊肉汤温阳散寒；红枣桂圆姜茶暖身；\n💆 穴位：艾灸关元、命门穴，睡前搓热腰眼；\n🏃 运动：每日晒背20分钟，八段锦温和升阳；\n🚫 忌：冷饮、冰品、生冷海鲜。'
  },
  {
    keys: ['气血', '贫血', '气色差', '脸色差', '面色发黄', '月经量少'],
    reply: '【气血调养】气为血之帅，血为气之母，气血双补是关键。\n🍲 食疗：黄芪党参乌鸡汤、红枣阿胶糕、桂圆红枣鸡蛋糖水；\n💆 穴位：常按三阴交、血海穴；\n😴 睡眠是最好的补血方式，23点前务必入睡；\n🚫 经期避免节食减肥与剧烈运动。'
  },
  {
    keys: ['上火', '口臭', '口腔溃疡', '长痘', '牙龈肿', '目赤', '湿热'],
    reply: '【清热降火】实火宜清，虚火宜滋。\n🍵 食疗：金银花茶、绿豆汤清实火；麦冬石斛茶滋阴降虚火；\n🥗 多吃苦瓜、芹菜、冬瓜，少食辛辣烧烤；\n💆 穴位：按揉内庭穴、曲池穴泄热；\n😴 熬夜最易上火，务必在23点前入睡。'
  },
  {
    keys: ['减肥', '瘦', '肥胖', '减脂', '体重', '瘦身'],
    reply: '【体重管理】中医减肥重在健脾祛湿、化痰消脂，而非单纯节食。\n🍵 饮品：薏米红豆水祛湿、决明子山楂茶消脂；\n🏃 运动：每日经络拍打操+快走40分钟；\n🥗 饮食：三分饥与寒，晚餐七分饱，忌夜宵；\n💆 穴位：按揉丰隆穴（化痰要穴）、天枢穴。'
  },
  {
    keys: ['肩颈', '颈椎', '腰痛', '腰酸', '久坐', '鼠标手', '脖子疼'],
    reply: '【颈肩腰调理】久坐伤肉，经络瘀滞则僵痛。\n🧘 跟练：推荐「办公室肩颈舒缓瑜伽」课程，每天15分钟；\n💆 穴位：按揉肩井穴、风池穴、后溪穴；\n🪑 工作：每45分钟起身活动，调整桌椅高度，屏幕与视线平齐；\n♨️ 热敷：睡前热敷肩颈10分钟促进循环。'
  },
  {
    keys: ['痛经', '月经', '经期', '例假', '妇科'],
    reply: '【经期调养】寒凝则痛，气滞则胀，温经散寒是根本。\n🍲 经前一周：艾叶红糖鸡蛋汤温经暖宫；避免冷饮；\n💆 穴位：按揉三阴交、关元穴，热水袋敷小腹；\n🧘 经期宜静养，可做温和拉伸，避免剧烈运动；\n⚠️ 痛经严重或周期紊乱，建议就医排查。'
  },
  {
    keys: ['湿气', '湿气重', '水肿', '舌苔厚', '大便黏', '身体沉重'],
    reply: '【祛湿调理】湿性黏浊，如油入面，健脾是祛湿之本。\n🍲 食疗：薏米红豆水、赤小豆冬瓜汤、茯苓白术鸡汤；\n🚫 少吃甜腻、生冷、油炸食物，少饮酒；\n💆 穴位：常按阴陵泉、丰隆穴；\n🏃 运动：每天微汗运动30分钟，湿气随汗而解。'
  },
  {
    keys: ['免疫力', '体质差', '容易感冒', '反复感冒', '抵抗力'],
    reply: '【增强体质】正气存内，邪不可干。\n🍲 食疗：黄精枸杞炖乳鸽、虫草花炖老鸭汤固本培元；\n🏃 运动：坚持八段锦，循序渐进；\n😴 睡眠充足、心情舒畅是免疫力的基石；\n🧣 换季注意保暖，春捂秋冻要适度。'
  },
  {
    keys: ['眼睛', '干眼', '视疲劳', '近视', '眼干', '眼涩'],
    reply: '【养肝明目】肝开窍于目，久视伤血。\n🍵 食疗：枸杞菊花茶、决明子茶清肝明目；多吃蓝莓、胡萝卜；\n💆 穴位：眼保健操轮刮眼眶，按揉睛明穴、太冲穴；\n📱 用眼：每用眼40分钟远眺5分钟，看绿色植物；\n😴 晚上11点前睡，肝血充足目自明。'
  }
]

const FALLBACK_REPLY = '谢谢你的提问。我是养生顾问小颐，擅长失眠、疲劳、脾胃、气血、祛湿、情志等日常调理建议。\n你可以试着问我：\n🌙 最近失眠怎么办？\n🍲 脾胃不好吃什么？\n💆 肩颈酸痛如何缓解？\n也可以点击下方快捷话题快速了解，或在「健康自测」模块获得完整辨证报告。'

export default {
  name: 'DigitalHuman',
  data() {
    return {
      topics: TOPICS,
      messages: [
        { from: 'bot', text: '你好，我是你的数字养生顾问小颐 🌿\n可以打字或点击麦克风说话向我提问，我会尽力为你解答。' }
      ],
      inputText: '',
      interimText: '',
      speaking: false,
      voiceOn: true,
      recording: false,
      recognition: null,
      keepListening: false,
      supportsSpeech: false
    }
  },
  created() {
    const SR = window.SpeechRecognition || window.webkitSpeechRecognition
    this.supportsSpeech = !!SR
  },
  beforeUnmount() {
    this.stopSpeak()
    this.stopRecord()
  },
  methods: {
    /* ===== 对话 ===== */
    ask(t) {
      this.pushMsg('user', t.q)
      this.reply(t.a)
    },
    send() {
      const text = (this.inputText || '').trim()
      if (!text) return
      this.inputText = ''
      this.pushMsg('user', text)
      const answer = this.matchKB(text)
      this.reply(answer)
    },
    pushMsg(from, text, interim) {
      this.messages.push({ from, text, interim: !!interim })
      this.$nextTick(() => {
        const box = this.$refs.chatBox
        if (box) box.scrollTop = box.scrollHeight
      })
    },
    reply(text) {
      // 模拟思考延迟，体验更自然
      setTimeout(() => {
        this.pushMsg('bot', text)
        this.speak(text)
      }, 350)
    },
    /* 知识库匹配：关键词加权评分，长词权重更高 */
    matchKB(text) {
      let best = null
      let bestScore = 0
      KB.forEach((item) => {
        let score = 0
        item.keys.forEach((w) => {
          if (text.includes(w)) {
            score += w.length >= 4 ? 4 : w.length >= 3 ? 3 : w.length >= 2 ? 2 : 1
          }
        })
        if (score > bestScore) {
          bestScore = score
          best = item
        }
      })
      return best ? best.reply : FALLBACK_REPLY
    },
    clearChat() {
      this.messages = [{ from: 'bot', text: '对话已清空。有什么养生问题想问我吗？🌿' }]
    },

    /* ===== 语音识别：点击开始 / 点击停止 ===== */
    toggleRecord() {
      if (!this.supportsSpeech) {
        alert('当前浏览器不支持语音识别，建议使用 Chrome 浏览器，或直接文字输入。\n（微信内置浏览器不支持语音识别 API）')
        return
      }
      if (this.recording) {
        this.stopRecord()
      } else {
        this.startRecord()
      }
    },
    startRecord() {
      try {
        const SR = window.SpeechRecognition || window.webkitSpeechRecognition
        const rec = new SR()
        rec.lang = 'zh-CN'
        rec.interimResults = true
        rec.continuous = true // 连续识别，直到用户点击停止
        rec.onresult = (e) => {
          let interim = ''
          let final = ''
          for (let i = e.resultIndex; i < e.results.length; i++) {
            const t = e.results[i][0].transcript
            if (e.results[i].isFinal) {
              final += t
            } else {
              interim += t
            }
          }
          this.interimText = interim
          if (final) {
            // 最终结果作为用户消息发送
            const text = final.trim()
            this.interimText = ''
            if (text) {
              this.inputText = ''
              this.pushMsg('user', text)
              this.reply(this.matchKB(text))
            }
          }
        }
        rec.onerror = (e) => {
          if (e.error === 'not-allowed' || e.error === 'service-not-allowed') {
            alert('麦克风权限被拒绝。\n请点击浏览器地址栏的锁图标 → 允许麦克风权限后重试。')
          } else if (e.error === 'no-speech') {
            // 静默重试
          } else if (e.error !== 'aborted') {
            console.warn('语音识别错误:', e.error)
          }
        }
        rec.onend = () => {
          // 浏览器有时自动断开，只要用户未手动停止就重启
          if (this.keepListening) {
            try {
              rec.start()
            } catch (e) {
              /* start 抛错时忽略，等待下次循环 */
            }
          } else {
            this.recording = false
            this.interimText = ''
          }
        }
        this.recognition = rec
        this.keepListening = true
        rec.start()
        this.recording = true
      } catch (e) {
        console.error('启动语音识别失败', e)
        alert('语音识别启动失败，请重试或直接文字输入。')
        this.recording = false
        this.keepListening = false
      }
    },
    stopRecord() {
      this.keepListening = false
      if (this.recognition) {
        try {
          this.recognition.stop()
        } catch (e) {
          /* 忽略停止异常 */
        }
        this.recognition = null
      }
      this.recording = false
      this.interimText = ''
    },

    /* ===== 语音播报 ===== */
    speak(text) {
      this.stopSpeak()
      if (!this.voiceOn || !('speechSynthesis' in window)) return
      // 长文本截断，避免播报过久
      const plain = text.replace(/\n/g, '。')
      const u = new SpeechSynthesisUtterance(plain.slice(0, 160))
      u.lang = 'zh-CN'
      u.rate = 1
      u.onstart = () => {
        this.speaking = true
      }
      u.onend = () => {
        this.speaking = false
      }
      u.onerror = () => {
        this.speaking = false
      }
      speechSynthesis.speak(u)
    },
    stopSpeak() {
      if ('speechSynthesis' in window) speechSynthesis.cancel()
      this.speaking = false
    }
  }
}
</script>

<style scoped>
.module-head h2 {
  margin: 0 0 6px;
  color: #2f5d50;
}
.module-head p {
  margin: 0 0 18px;
  color: #7a8a82;
  font-size: 14px;
}

/* 数字人舞台 */
.stage {
  background: linear-gradient(160deg, #eef6f1, #dcefe5);
  border-radius: 18px;
  padding: 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
}
.avatar {
  position: relative;
  width: 150px;
  height: 150px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.avatar-face {
  width: 120px;
  height: 120px;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 8px 24px rgba(47, 93, 80, 0.2);
  position: relative;
  z-index: 2;
}
.eye {
  position: absolute;
  top: 44px;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: #2f5d50;
